(4881992, 708881, 42135, '<td valign="top">The title is a bit screwy and I wish I could see just a bit more of you in this.</td>', 'The title is a bit screwy and I wish I could see just a bit more of you in this.', '2008-08-12 01:09:42.000000', NULL, 1),
(4881994, 707420, 42135, '<td valign="top">Very cute .. seems like a touch too much on the red tones.</td>', 'Very cute .. seems like a touch too much on the red tones.', '2008-08-12 01:10:03.000000', NULL, 1),
(4881998, 707372, 42135, '<td valign="top">Nice portrait!</td>', 'Nice portrait!', '2008-08-12 01:10:17.000000', NULL, 1),
(4881999, 708685, 42135, '<td valign="top">I like the background, it reflects the yellows of your jumpsuit giving a nice depth to the photo.</td>', 'I like the background, it reflects the yellows of your jumpsuit giving a nice depth to the photo.', '2008-08-12 01:11:04.000000', NULL, 1),
(4882001, 708782, 42135, '<td valign="top">Nice photo to portray the job.</td>', 'Nice photo to portray the job.', '2008-08-12 01:12:02.000000', NULL, 1),
(4882002, 709121, 42135, '<td valign="top">I think I know who this is :)  Very nice lighting</td>', 'I think I know who this is :)  Very nice lighting', '2008-08-12 01:12:34.000000', NULL, 1),
(4882006, 708906, 42135, '<td valign="top">Nice control on the focus.</td>', 'Nice control on the focus.', '2008-08-12 01:14:10.000000', NULL, 1),
(4882007, 708895, 42135, '<td valign="top">Awesome photo!</td>', 'Awesome photo!', '2008-08-12 01:14:27.000000', NULL, 1),
(4882009, 707489, 42135, '<td valign="top">I really like this but find the branches a bit distracting.</td>', 'I really like this but find the branches a bit distracting.', '2008-08-12 01:14:55.000000', NULL, 1),
(4882010, 709118, 42135, '<td valign="top">Lighting seems a bit too bright for a *worn* type of photo but nice DOF</td>', 'Lighting seems a bit too bright for a *worn* type of photo but nice DOF', '2008-08-12 01:15:59.000000', NULL, 1),
(4882011, 709115, 42135, '<td valign="top">Lots of space on the left making the main subject seem a bit centered.</td>', 'Lots of space on the left making the main subject seem a bit centered.', '2008-08-12 01:17:14.000000', NULL, 1),
