(4883255, 707489, 66310, '<td valign="top">Very creative! Oh, and if this is you, all I can say is.....beautiful!!</td>', 'Very creative! Oh, and if this is you, all I can say is.....beautiful!!', '2008-08-12 16:56:43.000000', NULL, 1),
(4883277, 708812, 66310, '<td valign="top">Great depiction. I not only like the light and shadows in this shot, but the solitude reflects the "out of work" position you are in. Great vision in the photo, and good luck with your acting!</td>', 'Great depiction. I not only like the light and shadows in this shot, but the solitude reflects the "out of work" position you are in. Great vision in the photo, and good luck with your acting!', '2008-08-12 17:04:54.000000', NULL, 1),
(4883280, 708936, 66310, '<td valign="top">I like the colors and the mirror that was used. Thank you for your service!</td>', 'I like the colors and the mirror that was used. Thank you for your service!', '2008-08-12 17:05:34.000000', NULL, 1),
