(4884512, 707632, 68573, '<td valign="top">A wonderful image and brilliantly lit.</td>', 'A wonderful image and brilliantly lit.', '2008-08-13 01:37:38.000000', NULL, 1),
(4884525, 708947, 93478, '<td valign="top">The rich copper stands out nicely against the black background.  The crop is a little tight on the left though.  Overall nice job.</td>', 'The rich copper stands out nicely against the black background.  The crop is a little tight on the left though.  Overall nice job.', '2008-08-13 01:40:50.000000', NULL, 1),
(4884533, 708783, 33672, '<td valign="top">Fantastic. Simply fantastic. 10</td>', 'Fantastic. Simply fantastic. 10', '2008-08-13 01:44:24.000000', NULL, 1),
(4884534, 708661, 93478, '<td valign="top">I don''t know if it''s a wide-angle lens that curves the cello body but its a little disconcerting.  The unbalanced frame -- thicker on top and bottom -- is distracting as well.</td>', 'I don''t know if it''s a wide-angle lens that curves the cello body but its a little disconcerting.  The unbalanced frame -- thicker on top and bottom -- is distracting as well.', '2008-08-13 01:44:33.000000', NULL, 1),
(4884535, 708770, 68573, '<td valign="top">A great composition, the composition is excellent and the black borders on side really work well to generate a lot of interest on the subject 9</td>', 'A great composition, the composition is excellent and the black borders on side really work well to generate a lot of interest on the subject 9', '2008-08-13 01:44:57.000000', NULL, 1),
(4884541, 708166, 93478, '<td valign="top">You''re trying to communicate a lot in this shot and I think as a result it lacks a real focus point.</td>', 'You''re trying to communicate a lot in this shot and I think as a result it lacks a real focus point.', '2008-08-13 01:46:59.000000', NULL, 1),
(4884543, 708328, 68573, '<td valign="top">i love the warm tones here. The perspective is great too</td>', 'i love the warm tones here. The perspective is great too', '2008-08-13 01:47:09.000000', NULL, 1),
(4884556, 708476, 93478, '<td valign="top">A unique view not seen often here.  Really would like to know how you got it.  It could use some color.</td>', 'A unique view not seen often here.  Really would like to know how you got it.  It could use some color.', '2008-08-13 01:51:37.000000', NULL, 1),
(4884564, 707489, 68573, '<td valign="top">Wonderful lighting. The background colors look unreal but work so well for this image. The centered composition looks perfect for this shot and overall a great take 9</td>', 'Wonderful lighting. The background colors look unreal but work so well for this image. The centered composition looks perfect for this shot and overall a great take 9', '2008-08-13 01:54:33.000000', NULL, 1),
(4884565, 708936, 93478, '<td valign="top">Wow, that''s a lot of ribbons.  The colors stand out nicely without oversaturation.  I like how the U.S. pins(?) reflect the flag.</td>', 'Wow, that''s a lot of ribbons.  The colors stand out nicely without oversaturation.  I like how the U.S. pins(?) reflect the flag.', '2008-08-13 01:54:33.000000', NULL, 1),
(4884572, 708327, 93478, '<td valign="top">Nice choice of colorful items.  Could have use more saturation however.</td>', 'Nice choice of colorful items.  Could have use more saturation however.', '2008-08-13 01:55:29.000000', NULL, 1),
(4884573, 708783, 68573, '<td valign="top">Looks way too over sharpened to me</td>', 'Looks way too over sharpened to me', '2008-08-13 01:56:05.000000', NULL, 1),
