(4885113, 708854, 97313, '<td valign="top">The arrangement around the keyboard is bad, the font chosen doesn''t make the screen exciting. Maybe a bit more centered would have helped.</td>', 'The arrangement around the keyboard is bad, the font chosen doesn''t make the screen exciting. Maybe a bit more centered would have helped.', '2008-08-13 08:08:21.000000', NULL, 1),
