(4885149, 708866, 97313, '<td valign="top">A bit of the hat is missing and maybe you could have tried to frame without the corner of the rug on the top right.</td>', 'A bit of the hat is missing and maybe you could have tried to frame without the corner of the rug on the top right.', '2008-08-13 08:16:46.000000', NULL, 1),
